INSERT INTO pages VALUES(1,'home','Welcome to Ganesh The Family Restaurant',replace('<p class="lead">Committed to quality, served with love. We are Ahmedabad''s favourite destination for <strong>South Indian Dosa</strong>, <strong>Kathiyawadi specials</strong>, <strong>Umbadiyu</strong>, and authentic family dining.</p>\n<p>From classic Paper Dosa to our famous <strong>Burj Khalifa Dosa</strong>, Rajasthani Daal-Bati, and Punjabi Paneer — every dish is prepared fresh with care.</p>\n<ul><li>Umbadiyu Specialist</li><li>Dosa & Uttapam varieties</li><li>Kathiyawadi & Rajasthani cuisine</li><li>Online ordering available</li></ul>','\n',char(10)),'Ganesh The Family Restaurant | Gota Ahmedabad',NULL,1,'2026-09-07 10:11:03','2026-09-07 10:25:07');
INSERT INTO pages VALUES(2,'about','About Ganesh The Family Restaurant',replace('<p>Ganesh The Family Restaurant is located on <strong>Jagatpur Road, Gota</strong> — in front of Rangoli, beside Magnate Luxuria. We welcome families, friends, and food lovers with warm hospitality and honest flavours.</p>\n<p>Our menu celebrates Gujarat and India: crispy dosas, Surati Mysore specials, Kathiyawadi gathiya, original Rajasthani Daal-Bati, rich paneer gravies, and fresh tandoor breads.</p>\n<p><strong>Contact:</strong> 9276819283 / 8200692794 · info@ganeshtfr.com</p>','\n',char(10)),NULL,NULL,1,'2026-09-07 10:11:03','2026-09-07 10:25:07');
