INSERT INTO founders VALUES(1,'Ganesh Patel','Founder & Head Chef','Started Ganesh The Family Restaurant with a vision to serve honest Gujarati and South Indian food. 25+ years in hospitality — Umbadiyu and Dosa specialist.','https://images.unsplash.com/photo-1560250097-0b93528c311a?w=400&q=80',1,1,'2026-09-07 12:59:49','2026-09-07 12:59:49');
INSERT INTO founders VALUES(2,'Priya Shah','Co-Founder & Operations','Manages daily operations, quality control, and guest experience. Ensures every family feels at home at our Gota restaurant.','https://images.unsplash.com/photo-1573496359142-b8d87734a5a2?w=400&q=80',2,1,'2026-09-07 12:59:49','2026-09-07 12:59:49');
INSERT INTO customer_reviews VALUES(1,'Riddhi Ghaghada',5,5,5,5,'All the food is extremely delicious. Among them, UMBADIYU tasted amazing and is truly one of the best in all of Ahmedabad. You should definitely try it..😋','google','7 months ago',1,1,1,'2026-09-07 15:37:10','2026-09-07 15:37:10');
INSERT INTO customer_reviews VALUES(2,'Fresha Patel',5,5,5,5,'Absolutely amazing Umbadiyu! Not spicy at all, yet full of authentic flavor. Truly delicious and a must-visit place','google','8 months ago',1,1,2,'2026-09-07 15:37:10','2026-09-07 15:37:10');
INSERT INTO customer_reviews VALUES(3,'Urvil Sarvasva',5,5,5,5,'Excellent umbaiyu. Glad we now have umbadiyu place in gota. They serve it with chutneys which is great as eating umbadiyu alone is not great to swallow. Chutneys with umbadiyu are definately worth it.','google','9 months ago',1,1,3,'2026-09-07 15:37:10','2026-09-07 15:37:10');
INSERT INTO customer_reviews VALUES(4,'Ghanshyam Solanki',5,5,4,4,'Delicious food, mainly umbadiyu is testy.','google','7 months ago',1,1,4,'2026-09-07 15:37:10','2026-09-07 15:37:10');
INSERT INTO customer_reviews VALUES(5,'Kajal Patel',5,5,5,5,'It was awesome taste....first time try ... & it was so good','google','9 months ago',1,1,5,'2026-09-07 15:37:10','2026-09-07 15:37:10');
