PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE IF NOT EXISTS "migrations" ("id" integer primary key autoincrement not null, "migration" varchar not null, "batch" integer not null);
CREATE TABLE IF NOT EXISTS "users" ("id" integer primary key autoincrement not null, "name" varchar not null, "email" varchar not null, "email_verified_at" datetime, "password" varchar not null, "remember_token" varchar, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "password_reset_tokens" ("email" varchar not null, "token" varchar not null, "created_at" datetime, primary key ("email"));
CREATE TABLE IF NOT EXISTS "sessions" ("id" varchar not null, "user_id" integer, "ip_address" varchar, "user_agent" text, "payload" text not null, "last_activity" integer not null, primary key ("id"));
CREATE TABLE IF NOT EXISTS "cache" ("key" varchar not null, "value" text not null, "expiration" integer not null, primary key ("key"));
CREATE TABLE IF NOT EXISTS "cache_locks" ("key" varchar not null, "owner" varchar not null, "expiration" integer not null, primary key ("key"));
CREATE TABLE IF NOT EXISTS "jobs" ("id" integer primary key autoincrement not null, "queue" varchar not null, "payload" text not null, "attempts" integer not null, "reserved_at" integer, "available_at" integer not null, "created_at" integer not null);
CREATE TABLE IF NOT EXISTS "job_batches" ("id" varchar not null, "name" varchar not null, "total_jobs" integer not null, "pending_jobs" integer not null, "failed_jobs" integer not null, "failed_job_ids" text not null, "options" text, "cancelled_at" integer, "created_at" integer not null, "finished_at" integer, primary key ("id"));
CREATE TABLE IF NOT EXISTS "failed_jobs" ("id" integer primary key autoincrement not null, "uuid" varchar not null, "connection" text not null, "queue" text not null, "payload" text not null, "exception" text not null, "failed_at" datetime not null default CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS "site_settings" ("id" integer primary key autoincrement not null, "key" varchar not null, "value" text, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "pages" ("id" integer primary key autoincrement not null, "slug" varchar not null, "title" varchar not null, "content" text, "meta_title" varchar, "meta_description" text, "is_published" tinyint(1) not null default '1', "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "menu_categories" ("id" integer primary key autoincrement not null, "name" varchar not null, "description" text, "image" varchar, "sort_order" integer not null default '0', "is_active" tinyint(1) not null default '1', "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "menu_items" ("id" integer primary key autoincrement not null, "menu_category_id" integer not null, "name" varchar not null, "description" text, "price" numeric not null, "image" varchar, "is_veg" tinyint(1) not null default '1', "is_available" tinyint(1) not null default '1', "sort_order" integer not null default '0', "created_at" datetime, "updated_at" datetime, "name_gu" varchar, foreign key("menu_category_id") references "menu_categories"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "orders" ("id" integer primary key autoincrement not null, "order_no" varchar not null, "customer_name" varchar not null, "phone" varchar not null, "email" varchar, "address" text, "notes" text, "total_amount" numeric not null default '0', "status" varchar not null default 'pending', "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "order_items" ("id" integer primary key autoincrement not null, "order_id" integer not null, "menu_item_id" integer, "item_name" varchar not null, "quantity" integer not null default '1', "unit_price" numeric not null, "line_total" numeric not null, "created_at" datetime, "updated_at" datetime, foreign key("order_id") references "orders"("id") on delete cascade, foreign key("menu_item_id") references "menu_items"("id") on delete set null);
CREATE TABLE IF NOT EXISTS "vegetables" ("id" integer primary key autoincrement not null, "name" varchar not null, "type" varchar not null default 'vegetable', "image" varchar, "retail_price_per_kg" numeric not null, "vendor_price_per_kg" numeric, "unit" varchar not null default 'kg', "is_active" tinyint(1) not null default '1', "sort_order" integer not null default '0', "created_at" datetime, "updated_at" datetime, "description" text, "name_hi" varchar, "name_gu" varchar, "description_hi" text, "description_gu" text);
CREATE TABLE IF NOT EXISTS "vegetable_price_logs" ("id" integer primary key autoincrement not null, "vegetable_id" integer not null, "retail_price_per_kg" numeric not null, "vendor_price_per_kg" numeric, "logged_date" date not null, "changed_by" integer, "note" text, "created_at" datetime, "updated_at" datetime, foreign key("vegetable_id") references "vegetables"("id") on delete cascade, foreign key("changed_by") references "users"("id") on delete set null);
CREATE TABLE IF NOT EXISTS "staff" ("id" integer primary key autoincrement not null, "name" varchar not null, "phone" varchar, "email" varchar, "role" varchar, "joining_date" date, "monthly_salary" numeric not null default '0', "is_active" tinyint(1) not null default '1', "notes" text, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "salary_transactions" ("id" integer primary key autoincrement not null, "staff_id" integer not null, "type" varchar not null, "amount" numeric not null, "transaction_date" date not null, "month" integer, "year" integer, "note" text, "created_at" datetime, "updated_at" datetime, foreign key("staff_id") references "staff"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "gallery_categories" ("id" integer primary key autoincrement not null, "name" varchar not null, "sort_order" integer not null default '0', "is_active" tinyint(1) not null default '1', "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "gallery_images" ("id" integer primary key autoincrement not null, "gallery_category_id" integer, "title" varchar, "image" varchar not null, "caption" text, "sort_order" integer not null default '0', "is_active" tinyint(1) not null default '1', "created_at" datetime, "updated_at" datetime, foreign key("gallery_category_id") references "gallery_categories"("id") on delete set null);
CREATE TABLE IF NOT EXISTS "video_categories" ("id" integer primary key autoincrement not null, "name" varchar not null, "sort_order" integer not null default '0', "is_active" tinyint(1) not null default '1', "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "videos" ("id" integer primary key autoincrement not null, "video_category_id" integer, "title" varchar not null, "description" text, "youtube_url" varchar, "video_file" varchar, "thumbnail" varchar, "sort_order" integer not null default '0', "is_active" tinyint(1) not null default '1', "created_at" datetime, "updated_at" datetime, foreign key("video_category_id") references "video_categories"("id") on delete set null);
CREATE TABLE IF NOT EXISTS "portfolios" ("id" integer primary key autoincrement not null, "title" varchar not null, "description" text, "image" varchar, "event_date" date, "sort_order" integer not null default '0', "is_active" tinyint(1) not null default '1', "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "sops" ("id" integer primary key autoincrement not null, "title" varchar not null, "category" varchar, "content" text, "document" varchar, "version" varchar not null default '1.0', "is_active" tinyint(1) not null default '1', "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "contact_messages" ("id" integer primary key autoincrement not null, "name" varchar not null, "email" varchar, "phone" varchar, "subject" varchar, "message" text not null, "is_read" tinyint(1) not null default '0', "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "order_activity_logs" ("id" integer primary key autoincrement not null, "order_id" integer not null, "action" varchar not null, "status" varchar, "note" text, "user_id" integer, "created_at" datetime, "updated_at" datetime, foreign key("order_id") references "orders"("id") on delete cascade, foreign key("user_id") references "users"("id") on delete set null);
CREATE TABLE IF NOT EXISTS "vegetable_sales" ("id" integer primary key autoincrement not null, "vegetable_id" integer not null, "grams" numeric not null, "price_type" varchar not null default 'retail', "unit_price_per_kg" numeric not null, "total_price" numeric not null, "sold_date" date not null, "customer_note" varchar, "recorded_by" integer, "created_at" datetime, "updated_at" datetime, foreign key("vegetable_id") references "vegetables"("id") on delete cascade, foreign key("recorded_by") references "users"("id") on delete set null);
CREATE TABLE IF NOT EXISTS "team_members" ("id" integer primary key autoincrement not null, "name" varchar not null, "role" varchar, "bio" text, "photo" varchar, "phone" varchar, "sort_order" integer not null default '0', "is_active" tinyint(1) not null default '1', "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "home_sliders" ("id" integer primary key autoincrement not null, "title" varchar, "subtitle" text, "image" varchar not null, "link" varchar, "sort_order" integer not null default '0', "is_active" tinyint(1) not null default '1', "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "promotions" ("id" integer primary key autoincrement not null, "title" varchar, "image" varchar not null, "link" varchar, "is_active" tinyint(1) not null default '1', "show_once" tinyint(1) not null default '1', "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "founders" ("id" integer primary key autoincrement not null, "name" varchar not null, "title" varchar, "bio" text, "photo" varchar, "sort_order" integer not null default '0', "is_active" tinyint(1) not null default '1', "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "customer_reviews" ("id" integer primary key autoincrement not null, "reviewer_name" varchar not null, "rating" integer not null default '5', "food_rating" integer, "service_rating" integer, "atmosphere_rating" integer, "comment" text not null, "source" varchar not null default 'google', "reviewed_ago" varchar, "is_featured" tinyint(1) not null default '1', "is_active" tinyint(1) not null default '1', "sort_order" integer not null default '0', "created_at" datetime, "updated_at" datetime);
DELETE FROM sqlite_sequence;
CREATE UNIQUE INDEX "users_email_unique" on "users" ("email");
CREATE INDEX "sessions_user_id_index" on "sessions" ("user_id");
CREATE INDEX "sessions_last_activity_index" on "sessions" ("last_activity");
CREATE INDEX "jobs_queue_index" on "jobs" ("queue");
CREATE UNIQUE INDEX "failed_jobs_uuid_unique" on "failed_jobs" ("uuid");
CREATE UNIQUE INDEX "site_settings_key_unique" on "site_settings" ("key");
CREATE UNIQUE INDEX "pages_slug_unique" on "pages" ("slug");
CREATE UNIQUE INDEX "orders_order_no_unique" on "orders" ("order_no");
COMMIT;
